class SuiteLogger:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 3

    def __init__(self):
        if not "--dryrun" in sys.argv:
            self.ROBOT_LIBRARY_LISTENER = self
            self.destination_dir = None
            self.pipeline_skip = False
        else:
            self.pipeline_skip = True

    def start_suite(self, data, result):
        if not self.pipeline_skip:
            # # if get_config_variable(["output_dir"]):
            # #suite_path = get_config_variable(["output_dir"])
            # timestamp = datetime.now().strftime('%Y%m%d-%H%M%S')
            # suite_name = data.name.replace(' ', '_')  # Replace spaces with underscores
            # self.destination_dir = f'{suite_name}/{timestamp}'
            # # self.xml_logger.start_suite(result)
            # message = f"Relative Destination path if output directory is provided: {self.destination_dir}"
            # logger.console(message)         # Logs to the console
            # logger.info(message)
            directory = subprocess.check_output('pwd', shell=True)
            if os.path.exists('{0}/execution_logs'.format(decode_str(directory.strip()))):
                os.system('sudo  rm -rf  {0}/execution_logs'.format(decode_str(directory.strip())))
            self._log_suite_dut_data()

    def end_suite(self, data, result):
        if not self.pipeline_skip: #and get_config_variable(["output_dir"]):
            # suite_path = get_config_variable(["output_dir"])
            # # timestamp = datetime.now().strftime('%Y%m%d-%H%M%S')
            # # suite_name = data.name.replace(' ', '_')  # Replace spaces with underscores
            # self.destination_dir = f'{suite_path}/{self.destination_dir}'
            # os.makedirs(self.destination_dir, exist_ok=True)
            # shutil.copytree('execution_logs', f'{self.destination_dir}/execution_logs')
            # shutil.copy2('output.xml', self.destination_dir)
            if AdminFactory.get_instance().admin:
                AdminFactory.get_instance().admin.teardown_all_aliases_for_admin()
                AdminFactory.get_instance().admin_infomodel.teardown_all_aliases_for_infomodel()
            elif BtssmFactory.get_instance().oam_tool:
                BtssmFactory.get_instance().oam_tool.teardown_all_aliases_for_btssm()

    def _log_suite_dut_data(self):
        build_metadata = []
        bts_build = self.get_bts_version()
        if bts_build == 1:
            build_metadata.append("BTS software version" + ' : ' + 'Not Available')
        else:
            build_metadata.append("BTS software version" + ' : ' + bts_build)
        message = f"Build meta data {build_metadata}"
        logger.console(message)         # Logs to the console
        logger.info(message)

    def get_bts_version(self):
        """Get bts version"""
        try:
            tragetbd_filename = subprocess.check_output(
                "sshpass -p oZPS0POrRieRtu ssh toor4nsn@192.168.255.129 ls /ffs/run  2>/dev/null| grep 'Target' -m 1",
                shell=True)
            bts_build = tragetbd_filename[9:40]
            return decode_str(bts_build)
        except Exception:
            return 1
